<template><div class="page"><div class="page-title"><h2>预警中心</h2><el-button type="primary" @click="evaluate">立即评估</el-button></div><div class="stats"><div v-for="key in ['total','open','acked','resolved']" :key="key" class="stat"><div class="label">{{ labels[key] }}</div><div class="value">{{ stats[key] || 0 }}</div></div></div><div class="panel"><div class="toolbar"><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="开放" value="OPEN" /><el-option label="已确认" value="ACKED" /><el-option label="已解决" value="RESOLVED" /><el-option label="已忽略" value="IGNORED" /></el-select></div><el-table :data="rows" stripe><el-table-column prop="severity" label="等级" width="90" /><el-table-column prop="title" label="预警标题" /><el-table-column prop="type" label="规则类型" /><el-table-column prop="targetKey" label="对象" /><el-table-column prop="status" label="状态" /><el-table-column label="操作" width="250"><template #default="{ row }"><el-button v-if="row.status==='OPEN'" link @click="operate(row,'ack')">确认</el-button><el-button v-if="row.status==='OPEN'" link @click="operate(row,'resolve')">解决</el-button><el-button v-if="row.status==='OPEN'" link type="primary" @click="suggest(row)">执行建议</el-button></template></el-table-column></el-table></div></div></template>
<script setup>
import { reactive, ref } from 'vue'; import { alertApi } from '../api'; import { ElMessage } from 'element-plus'
const rows = ref([]); const status = ref(''); const stats = reactive({}); const labels = { total:'预警总数', open:'开放', acked:'已确认', resolved:'已解决' }
async function load() { rows.value = await alertApi.page({ status: status.value }); Object.assign(stats, await alertApi.stats()) }; async function evaluate() { await alertApi.evaluate(); ElMessage.success('评估完成'); load() }; async function operate(row, type) { await alertApi[type](row.id); load() }; async function suggest(row) { await alertApi.action(row.id); ElMessage.success('建议已执行'); load() }; load()
</script>
